```python
def generate_commands(vlan_id, to_set, to_remove):
    commands = []

    # Check if the VLAN should be removed
    if "vlan_id" in to_remove:
        return ["no vlan {0}".format(vlan_id)]

    # Generate commands for settings to apply
    for key, value in to_set.items():
        if key == "vlan_id" or value is None:
            continue

        # Avoid adding a command if it's already marked for removal
        if key in to_remove:
            commands.append("no {0}".format(key))
        else:
            commands.append("{0} {1}".format(key, value))

    # Generate commands for removals
    for key in to_remove:
        if key != "vlan_id":  # Ensure we don't add "no vlan ..."
            commands.append("no {0}".format(key))

    # Add VLAN definition at the start if there are commands to execute
    if commands:
        commands.insert(0, "vlan {0}".format(vlan_id))

    return commands
```

